// 动员·受伤失去（csx 行为引用样本）：本卡受到伤害 → 撤销「动员」（经 EffectRuntime 受控入口）。
Func<Orc.Cards.CardEventView, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Host is not Orc.Cards.Card card)
    {
        return;
    }

    if (view.Card is not Orc.Cards.Card damaged || !object.ReferenceEquals(damaged, card))
    {
        return; // 非本卡受到伤害：不处理
    }

    var runtime = Orc.Game.Effects.EffectRuntime.ResolveFor(card);
    if (runtime is null)
    {
        return; // 对局服务不可达：降级跳过（独立构造等）
    }

    await runtime.RevokeAsync(card, Orc.Game.Cards.KeywordIds.Mobilize, ct);
};
